insert into bsti_sunscreens(id,name_ko,note,ref_codes) values ('tint','징크옥사이드 + 아이언옥사이드 (틴티드, 젤)','UV·가시광선 차단 → 색소 재발 예방',ARRAY['S13','S14']);
insert into bsti_sunscreens(id,name_ko,note,ref_codes) values ('tintCream','징크옥사이드 + 아이언옥사이드 (틴티드, 크림)','건성+색소용, 가시광선 차단·보습',ARRAY['S13','S14']);
insert into bsti_sunscreens(id,name_ko,note,ref_codes) values ('mineral','무기자차 (징크옥사이드·티타늄디옥사이드)','민감성 저자극·광안정',ARRAY['S15']);
insert into bsti_sunscreens(id,name_ko,note,ref_codes) values ('mineralGel','무기자차 (젤 제형)','지성+민감용 저자극',ARRAY['S15']);
insert into bsti_sunscreens(id,name_ko,note,ref_codes) values ('organic','유기자차 (젤/플루이드)','백탁 없고 발림성 우수',ARRAY['S15']);
insert into bsti_sunscreens(id,name_ko,note,ref_codes) values ('basic','보습형 광범위 자차','제형 무관, 예방 중심',ARRAY['S14']);
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('OSPW','진정이 먼저인 풀코스 케어 수련생','진정·선크림으로 기초를 다진 뒤 미백→안티에이징 순서로 하나씩 도전.','O','S','P','W','지성 · 민감 · 색소 · 주름 피부. 피지 조절을 기본으로, 저자극 진정 위주로 강한 성분은 저농도·유도체로 관리하고, 멜라닌 억제 + 가시광선 차단 자차, 레티놀·비타민C로 콜라겐 자극이 핵심.',ARRAY['진정·장벽','선크림','미백','안티에이징'],'tint');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('OSPT','피지 잡는 순한 톤업 전문가','유분 조절 + 나이아신아마이드 같은 순한 미백으로 잡티 케어.','O','S','P','T','지성 · 민감 · 색소 · 탱탱 피부. 피지 조절을 기본으로, 저자극 진정 위주로 강한 성분은 저농도·유도체로 관리하고, 멜라닌 억제 + 가시광선 차단 자차, 항산화로 노화 예방이 핵심.',ARRAY['진정·장벽','선크림','미백'],'tint');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('OSNW','진정 먼저 주름 대비하는 장벽 건축가','장벽을 튼튼히 쌓은 뒤 저자극 레티놀로 노화 대비.','O','S','N','W','지성 · 민감 · 비색소 · 주름 피부. 피지 조절을 기본으로, 저자극 진정 위주로 강한 성분은 저농도·유도체로 관리하고, 자외선차단 예방, 레티놀·비타민C로 콜라겐 자극이 핵심.',ARRAY['진정·장벽','선크림','안티에이징'],'mineralGel');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('OSNT','수분만 챙기는 속예민 물광 미니멀리스트','가벼운 보습과 장벽 케어, 제품은 적게.','O','S','N','T','지성 · 민감 · 비색소 · 탱탱 피부. 피지 조절을 기본으로, 저자극 진정 위주로 강한 성분은 저농도·유도체로 관리하고, 자외선차단 예방, 항산화로 노화 예방이 핵심.',ARRAY['진정·장벽','선크림'],'mineralGel');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('ORPW','미백·주름 성분 풀가동하는 강철 케어러','튼튼한 피부라 레티놀+비타민C 적극 활용 가능.','O','R','P','W','지성 · 저항 · 색소 · 주름 피부. 피지 조절을 기본으로, 강한 활성성분도 사용 가능하게 관리하고, 멜라닌 억제 + 가시광선 차단 자차, 레티놀·비타민C로 콜라겐 자극이 핵심.',ARRAY['피지·모공','선크림','미백','안티에이징'],'tint');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('ORPT','피지·잡티 잡는 탄탄 톤업러','유분 조절 + 미백 집중, 선크림으로 재발 방지.','O','R','P','T','지성 · 저항 · 색소 · 탱탱 피부. 피지 조절을 기본으로, 강한 활성성분도 사용 가능하게 관리하고, 멜라닌 억제 + 가시광선 차단 자차, 항산화로 노화 예방이 핵심.',ARRAY['피지·모공','선크림','미백'],'tint');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('ORNW','안티에이징에 올인하는 광채 수호자','자극 걱정 없이 레티놀·펩타이드 마음껏.','O','R','N','W','지성 · 저항 · 비색소 · 주름 피부. 피지 조절을 기본으로, 강한 활성성분도 사용 가능하게 관리하고, 자외선차단 예방, 레티놀·비타민C로 콜라겐 자극이 핵심.',ARRAY['피지·모공','선크림','안티에이징'],'organic');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('ORNT','기본만으로 완성되는 타고난 꿀피부 우등생','세안·보습·선크림 기본 루틴이면 충분.','O','R','N','T','지성 · 저항 · 비색소 · 탱탱 피부. 피지 조절을 기본으로, 강한 활성성분도 사용 가능하게 관리하고, 자외선차단 예방, 항산화로 노화 예방이 핵심.',ARRAY['피지·모공','선크림'],'organic');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('DSPW','장벽부터 쌓아 올리는 종합 케어 도전자','보습·장벽 최우선, 미백·안티에이징은 순한 것부터 천천히.','D','S','P','W','건성 · 민감 · 색소 · 주름 피부. 장벽 보습을 기본으로, 저자극 진정 위주로 강한 성분은 저농도·유도체로 관리하고, 멜라닌 억제 + 가시광선 차단 자차, 레티놀·비타민C로 콜라겐 자극이 핵심.',ARRAY['진정·장벽','선크림','미백','안티에이징'],'tintCream');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('DSPT','보습 위에 미백 얹는 예민 잡티 진정가','진정+보습으로 바탕을 만들고 저자극 미백 추가.','D','S','P','T','건성 · 민감 · 색소 · 탱탱 피부. 장벽 보습을 기본으로, 저자극 진정 위주로 강한 성분은 저농도·유도체로 관리하고, 멜라닌 억제 + 가시광선 차단 자차, 항산화로 노화 예방이 핵심.',ARRAY['진정·장벽','선크림','미백'],'tintCream');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('DSNW','수분으로 주름 늦추는 보습 레이어링 장인','히알루론산+세라마이드 레이어링, 안티에이징은 펩타이드로.','D','S','N','W','건성 · 민감 · 비색소 · 주름 피부. 장벽 보습을 기본으로, 저자극 진정 위주로 강한 성분은 저농도·유도체로 관리하고, 자외선차단 예방, 레티놀·비타민C로 콜라겐 자극이 핵심.',ARRAY['진정·장벽','선크림','안티에이징'],'mineral');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('DSNT','보습 하나로 빛나는 미니멀 루틴가','자극 줄이고 보습만 잘해도 충분.','D','S','N','T','건성 · 민감 · 비색소 · 탱탱 피부. 장벽 보습을 기본으로, 저자극 진정 위주로 강한 성분은 저농도·유도체로 관리하고, 자외선차단 예방, 항산화로 노화 예방이 핵심.',ARRAY['진정·장벽','선크림'],'mineral');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('DRPW','보습 깔고 잡티·주름 공략하는 케어 전략가','보습 베이스 위에 레티놀·비타민C 활용.','D','R','P','W','건성 · 저항 · 색소 · 주름 피부. 장벽 보습을 기본으로, 강한 활성성분도 사용 가능하게 관리하고, 멜라닌 억제 + 가시광선 차단 자차, 레티놀·비타민C로 콜라겐 자극이 핵심.',ARRAY['보습·장벽','선크림','미백','안티에이징'],'tintCream');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('DRPT','선크림이 무기인 차분한 톤업 관리자','보습+미백 투트랙, 자외선 차단이 핵심.','D','R','P','T','건성 · 저항 · 색소 · 탱탱 피부. 장벽 보습을 기본으로, 강한 활성성분도 사용 가능하게 관리하고, 멜라닌 억제 + 가시광선 차단 자차, 항산화로 노화 예방이 핵심.',ARRAY['보습·장벽','선크림','미백'],'tintCream');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('DRNW','항산화로 시간을 붙잡는 맑은 피부 지킴이','보습에 항산화·콜라겐 케어를 더해 주름 속도 늦추기.','D','R','N','W','건성 · 저항 · 비색소 · 주름 피부. 장벽 보습을 기본으로, 강한 활성성분도 사용 가능하게 관리하고, 자외선차단 예방, 레티놀·비타민C로 콜라겐 자극이 핵심.',ARRAY['보습·장벽','선크림','안티에이징'],'basic');
insert into bsti_skin_types(code,persona_name,tagline,oil,sensitivity,pigment,aging,summary,care_order,sunscreen_id) values ('DRNT','수분 충전만으로 완성되는 저관리 꿀피부 소유자','보습·선크림 루틴이면 끝.','D','R','N','T','건성 · 저항 · 비색소 · 탱탱 피부. 장벽 보습을 기본으로, 강한 활성성분도 사용 가능하게 관리하고, 자외선차단 예방, 항산화로 노화 예방이 핵심.',ARRAY['보습·장벽','선크림'],'basic');
