-- BSTI 피부유형 성분추천 · Supabase(PostgreSQL) 스키마 + 시드
-- 생성 자동화 스크립트 산출물. Supabase SQL Editor에 그대로 실행.
-- 실행 순서: 이 파일 한 번 실행하면 스키마 생성 + 시드 + 채점 함수까지 완료됩니다.

begin;
drop table if exists bsti_type_ingredients, bsti_question_options, bsti_questions, bsti_skin_types, bsti_sunscreens, bsti_ingredients, bsti_axes, bsti_references cascade;

create table bsti_references (code text primary key, title text not null, url text not null);
create table bsti_axes (code text primary key, label text not null, high_pole char(1) not null, high_label text not null, low_pole char(1) not null, low_label text not null, question_count int not null, cutoff numeric not null);
create table bsti_ingredients (id text primary key, name_ko text not null, inci text, role text, category text not null, ref_codes text[] default '{}');
create table bsti_sunscreens (id text primary key, name_ko text not null, note text, ref_codes text[] default '{}');
create table bsti_skin_types (code char(4) primary key, persona_name text not null, tagline text not null, oil char(1) not null, sensitivity char(1) not null, pigment char(1) not null, aging char(1) not null, summary text, care_order text[] not null, sunscreen_id text references bsti_sunscreens(id));
create table bsti_type_ingredients (id bigserial primary key, type_code char(4) references bsti_skin_types(code) on delete cascade, ingredient_id text references bsti_ingredients(id), relation text not null check (relation in ('recommend','avoid')), is_multibenefit boolean default false, sort_order int not null, unique(type_code, ingredient_id, relation));
create table bsti_questions (id int primary key, axis_code text references bsti_axes(code), position int not null, text text not null);
create table bsti_question_options (id bigserial primary key, question_id int references bsti_questions(id) on delete cascade, label text not null, score int not null check (score between 1 and 4), position int not null);

