-- bsti_axes (cutoff = 2.5 * question_count : 축 점수합 >= cutoff 이면 high_pole)

-- bsti_ingredients (권장 성분)
-- bsti_ingredients (기피 성분)

-- bsti_sunscreens

-- bsti_skin_types (16 유형 + 페르소나)

-- bsti_type_ingredients (유형별 권장/기피 성분 매핑)

-- bsti_questions + options (25문항, score 4=높은극 O/S/P/W)

-- 채점 규칙: 축별 선택 score 합 >= cutoff 이면 high_pole, 아니면 low_pole → oil,sensitivity,pigment,aging 순 4글자 코드
-- p_answers 예: {"1":4,"2":3, ... ,"20":2}  (question_id -> 선택한 보기 score)
create or replace function bsti_compute_code(p_answers jsonb) returns char(4) language plpgsql as $$
declare r record; s numeric; v_code text := '';
begin
  for r in select * from bsti_axes a order by array_position(array['oil','sensitivity','pigment','aging'], a.code) loop
    select coalesce(sum( (p_answers ->> q.id::text)::numeric ),0) into s from bsti_questions q where q.axis_code = r.code;
    v_code := v_code || case when s >= r.cutoff then r.high_pole else r.low_pole end;
  end loop;
  return v_code;
end $$;

-- 사용자 진단 결과 저장용(선택) 예시 테이블
create table if not exists bsti_user_diagnoses (id bigserial primary key, user_id uuid, answers jsonb not null, result_code char(4) references bsti_skin_types(code), created_at timestamptz default now());
-- INSERT 시 result_code := bsti_compute_code(answers) 로 채우면 됨.

-- 편의 함수: 답변 → 코드 + 유형 + 권장/기피 성분 + 자차 를 JSON 한 번에
create or replace function bsti_diagnose(p_answers jsonb)
returns jsonb language sql stable as $$
